conv_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled Conv2d forward kernel (bf16 in/out, fp32 accumulation).
// Each block computes a TILE_H x TILE_W tile of output pixels (one image)
// for ALL Cout output channels. Both the filter bank (Cout x Cin*KH*KW)
// and the required input tile (with halo) are staged into shared memory
// once per block, so overlapping input activations are fetched from global
// memory only once instead of being re-read by every neighboring window.
template <typename T, int CO>
__global__ void __launch_bounds__(1024) conv2d_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int KH, int KW,
    int stride, int pad,
    int Hout, int Wout)
{
  constexpr int Threads = 1024;
  constexpr int TILE_H  = 16;
  constexpr int TILE_W  = 16;
  constexpr int PIXELS  = TILE_H * TILE_W;   // 256 output pixels per block
  constexpr int CG      = Threads / PIXELS;  // 4 output-channel groups
  constexpr int OPC     = CO / CG;           // 8 channels per thread
  static_assert(CO % CG == 0, "CO must be divisible by channel groups");
  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int oh0 = blockIdx.y * TILE_H;
  const int ow0 = blockIdx.x * TILE_W;
  const int K = Cin * KH * KW;
  // Input tile extent needed to cover the output tile (halo included)
  const int IHt = (TILE_H - 1) * stride + KH;
  const int IWt = (TILE_W - 1) * stride + KW;
  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sYn = (int64_t)CO * Hout * Wout;
  // Global tensors (per-image views) via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride((int64_t)H * Win, (int64_t)Win, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Int<CO>{}, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Int<CO>{}, K),
      make_stride((int64_t)K, Int<1>{})
  );
  // Shared memory: weights (CO x K) followed by input tile (Cin x IHt x IWt)
  extern __shared__ float smem_raw[];
  auto sW = make_tensor(
      make_smem_ptr(smem_raw),
      make_shape(Int<CO>{}, K),
      make_stride(K, Int<1>{})
  );
  auto sX = make_tensor(
      make_smem_ptr(smem_raw + CO * K),
      make_shape(Cin, IHt, IWt),
      make_stride(IHt * IWt, IWt, Int<1>{})
  );
  // Stage the (small) filter bank into shared memory as fp32
  for (int idx = tid; idx < CO * K; idx += Threads) {
    int oc = idx / K;
    int t  = idx - oc * K;
    sW(oc, t) = (float)mW(oc, t);
  }
  // Stage the input tile (with halo) into shared memory as fp32.
  // Out-of-range halo locations are zero-filled (implicit zero padding).
  const int ih_base = oh0 * stride - pad;
  const int iw_base = ow0 * stride - pad;
  const int tile_elems = Cin * IHt * IWt;
  for (int idx = tid; idx < tile_elems; idx += Threads) {
    int iw = idx % IWt;
    int r  = idx / IWt;
    int ih = r % IHt;
    int ic = r / IHt;
    int gih = ih_base + ih;
    int giw = iw_base + iw;
    float v = 0.0f;
    if ((unsigned)gih < (unsigned)H && (unsigned)giw < (unsigned)Win) {
      v = (float)mX(ic, gih, giw);
    }
    sX(ic, ih, iw) = v;
  }
  __syncthreads();
  // Cooperative mapping: PIXELS threads per output-channel group, CG groups
  // cover all CO channels. Each thread owns one output pixel and only CO/CG
  // channels, cutting the per-thread accumulator registers by CGx (raising
  // occupancy, which was register-limited) while keeping smem weight reads
  // broadcast within warps and global stores coalesced along width.
  const int pix = tid % PIXELS;
  const int cg  = tid / PIXELS;
  const int oc0 = cg * OPC;
  const int th = pix / TILE_W;
  const int tw = pix - th * TILE_W;
  const int oh = oh0 + th;
  const int ow = ow0 + tw;
  const bool valid = (oh < Hout) && (ow < Wout);
  const int lh = th * stride;
  const int lw = tw * stride;
  // Register accumulators for this thread's channel group
  float acc[OPC];
  #pragma unroll
  for (int i = 0; i < OPC; ++i) {
    acc[i] = 0.0f;
  }
  // Loop over the K = Cin*KH*KW taps; activations now come from smem
  for (int t = 0; t < K; ++t) {
    int kw = t % KW;
    int r  = t / KW;
    int kh = r % KH;
    int ic = r / KH;
    const float xv = sX(ic, lh + kh, lw + kw);
    // Rank-1 update across this thread's channel group (broadcast reads)
    #pragma unroll
    for (int i = 0; i < OPC; ++i) {
      acc[i] += xv * sW(oc0 + i, t);
    }
  }
  // Epilogue: store results (coalesced along width)
  if (valid) {
    #pragma unroll
    for (int i = 0; i < OPC; ++i) {
      mY(oc0 + i, oh, ow) = static_cast<T>(acc[i]);
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x, torch::Tensor w, int stride, int padding) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, KH, KW]");
  TORCH_CHECK(x.scalar_type() == at::kBFloat16, "x must be bfloat16");
  TORCH_CHECK(w.scalar_type() == at::kBFloat16, "w must be bfloat16");
  TORCH_CHECK(stride > 0 && padding >= 0, "invalid stride/padding");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N    = x_c.size(0);
  const int64_t Cin  = x_c.size(1);
  const int64_t H    = x_c.size(2);
  const int64_t Win  = x_c.size(3);
  const int64_t Cout = w_c.size(0);
  const int64_t KH   = w_c.size(2);
  const int64_t KW   = w_c.size(3);

  TORCH_CHECK(w_c.size(1) == Cin, "w.size(1) must equal x channels");
  TORCH_CHECK(Cout == 32, "this kernel is specialized for Cout == 32");

  const int64_t Hout = (H + 2 * padding - KH) / stride + 1;
  const int64_t Wout = (Win + 2 * padding - KW) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");

  auto y = torch::empty({N, Cout, Hout, Wout}, x_c.options());

  constexpr int Threads = 1024;
  constexpr int TILE_H  = 16;
  constexpr int TILE_W  = 16;
  dim3 block(Threads);
  dim3 grid(
      (unsigned)((Wout + TILE_W - 1) / TILE_W),
      (unsigned)((Hout + TILE_H - 1) / TILE_H),
      (unsigned)N
  );
  const int K   = (int)(Cin * KH * KW);
  const int IHt = (TILE_H - 1) * stride + (int)KH;
  const int IWt = (TILE_W - 1) * stride + (int)KW;
  const int smem = (int)((Cout * K + Cin * IHt * IWt) * sizeof(float));
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_tiled_kernel<cute::bfloat16_t, 32><<<grid, block, smem, stream>>>(
      reinterpret_cast<const cute::bfloat16_t*>(x_c.data_ptr<at::BFloat16>()),
      reinterpret_cast<const cute::bfloat16_t*>(w_c.data_ptr<at::BFloat16>()),
      reinterpret_cast<cute::bfloat16_t*>(y.data_ptr<at::BFloat16>()),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)KH, (int)KW,
      stride, padding,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

